 "content": "def transform(grid):
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    colors = [v for v in counts if v != bg]
    if not colors:
        return out
    # For a row-pattern whose right edge is a non-background pixel, turn
    # the trailing background region into the marker color 1.
    for r, row in enumerate(grid):
        last = len(row) - 1
        while last >= 0 and row[last] == bg:
            last -= 1
        if last >= 0 and last < len(row) - 1:
            for c in range(last + 1, len(row)):
                out[r][c] = 1
    return out
