 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    # A later row may be a copy of an earlier template with its right-hand
    # foreground portion erased into the background. Mark the erased cells.
    for r in range(h):
        best = None
        for q in range(r):
            p = 0
            while p < w and grid[r][p] == grid[q][p]:
                p += 1
            if p >= max(3, w // 3) and p < w:
                # Only accept a suffix consisting of template foreground
                # replaced by the background in the repeated row.
                changed = [c for c in range(p, w)
                           if grid[q][c] != grid[r][c]]
                if changed and all(grid[r][c] == bg and grid[q][c] != bg
                                   for c in changed):
                    # Suffix after the first changed cell must be uniform-erased
                    # wherever the template has foreground.
                    if all(grid[r][c] == bg for c in range(p, w)):
                        if best is None or p > best[0]:
                            best = (p, q)
        if best is not None:
            p, q = best
            for c in range(p, w):
                if grid[r][c] == bg and grid[q][c] != bg:
                    out[r][c] = 1
    return out
