 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    # Find recurring 4-row motif blocks. If a later block is a partial
    # copy of an earlier one, color the missing foreground cells with 1.
    for r in range(h - 3):
        for q in range(r + 4, h - 3):
            # identical rows at corresponding positions in a 4-row block,
            # except where the later block has been erased to background.
            candidate = True
            for dr in range(4):
                for c in range(w):
                    a, b = grid[r+dr][c], grid[q+dr][c]
                    if b != a and b != bg:
                        candidate = False
                        break
                if not candidate:
                    break
            if not candidate:
                continue
            # Need actual erased foreground cells and at least one exact match.
            erased = [(dr,c) for dr in range(4) for c in range(w)
                      if grid[q+dr][c] == bg and grid[r+dr][c] != bg]
            if not erased:
                continue
            exact = sum(grid[r+dr][c] == grid[q+dr][c]
                        for dr in range(4) for c in range(w))
            if exact < 5:
                continue
            for dr,c in erased:
                out[q+dr][c] = 1
    return out
